mapper.select:
SELECT ce.id, ce.workspace_id, ce.correlation_id, ce.digest, ce.page_path, ce.reported_at
FROM client_error ce
JOIN workspace w ON w.id = ce.workspace_id
WHERE w.org_id = #{orgId}
  AND ce.reported_at >= #{since}
  AND ce.reported_at <= #{until}

    AND ce.correlation_id = CONVERT(#{correlationId} USING ascii) COLLATE ascii_bin

ORDER BY ce.reported_at ASC, ce.id ASC
LIMIT #{limit}
